   206→            child.setOrderOfArrival(s_globalOrderOfArrival++);
   207→
   208→            if (_running)
   209→            {
   210→                child.onEnter();
   211→                if (_isTransitionFinished)
   212→                    child.onEnterTransitionDidFinish();
   213→            }
   214→
   215→            if (_cascadeColorEnabled)
   216→            {
   217→                updateCascadeColor();
   218→            }
   219→
   220→            if (_cascadeOpacityEnabled)
