   272→        public virtual void enumerateChildren(string name, Func<CCNode, bool> callback)
   273→        {
   274→            Debug.Assert(!string.IsNullOrEmpty(name), "Invalid name");
   275→            Debug.Assert(callback != null, "Invalid callback function");
   276→
   277→            int length = name.Length;
   278→
   279→            int subStrStartPos = 0;
   280→            int subStrLength = length;
   281→
   282→            bool searchRecursively = false;
   283→            if (length > 2 && name[0] == '/' && name[1] == '/')
   284→            {
   285→                searchRecursively = true;
   286→                subStrStartPos = 2;
   287→                subStrLength -= 2;
   288→            }
   289→
   290→            bool searchFromParent = false;
   291→            if (length > 3 &&
   292→                name[length - 3] == '/' &&
   293→                name[length - 2] == '.' &&
   294→                name[length - 1] == '.')
   295→            {
   296→                searchFromParent = true;
   297→                subStrLength -= 3;
   298→            }
   299→
   300→            string newName = name.Substring(subStrStartPos, subStrLength);
   301→
   302→            if (searchFromParent)
   303→                newName.Insert(0, "[[:alnum:]]+/");
   304→
   305→            if (searchRecursively)
   306→            {
   307→                // name is '//xxx'
   308→                doEnumerateRecursive(this, newName, callback);
   309→            }
   310→            else
   311→            {
   312→                // name is xxx
   313→                doEnumerate(newName, callback);
   314→            }
   315→        }
