   327→        private bool doEnumerateRecursive(CCNode node, string name, Func<CCNode, bool> callback)
   328→        {
   329→            bool ret = false;
   330→            if (node.doEnumerate(name, callback))
   331→                ret = true;
   332→            else
   333→            {
   334→                foreach (var child in node.getChildren())
   335→                {
   336→                    if (doEnumerateRecursive(child, name, callback))
   337→                    {
   338→                        ret = true;
   339→                        break;
   340→                    }
   341→                }
   342→            }
   343→            return ret;
   344→        }
   345→
   346→        private bool doEnumerate(string name, Func<CCNode, bool> callback)
   347→        {
   348→            int pos = name.IndexOf('/');
   349→            string searchName = name;
   350→            bool needRecursive = false;
   351→            if (pos >= 0)
   352→            {
   353→                searchName = name.Substring(0, pos);
   354→                name = name.Substring(pos);
   355→                needRecursive = true;
   356→            }
   357→
   358→            bool ret = false;
   359→            foreach (var child in _children)
   360→            {
   361→                if (Regex.IsMatch(child._name, searchName))
   362→                {
   363→                    if (!needRecursive)
   364→                    {
   365→                        if (callback(child))
   366→                        {
   367→                            ret = true;
   368→                            break;
   369→                        }
   370→                    }
   371→                    else
   372→                    {
   373→                        ret = child.doEnumerate(name, callback);
   374→                        if (ret)
   375→                            break;
   376→                    }
   377→                }
   378→            }
   379→
   380→            return ret;
   381→        }
