   443→        public virtual void removeAllChildrenWithCleanup(bool cleanup)
   444→        {
   445→            _innerRemoveCall++;
   446→
   447→            foreach (var child in _children)
   448→            {
   449→                if (child.isRunning() && !this._running)
   450→                {
   451→                    CCLOG("No Call onExit");
   452→                }
   453→
   454→                if (this._running)
   455→                {
   456→                    child.onExitTransitionDidStart();
   457→                    child.onExit();
   458→                }
   459→
   460→                if (cleanup)
   461→                {
   462→                    child.cleanup();
   463→                }
   464→                child.setParent(null);
   465→            }
   466→            _innerRemoveCall--;
   467→
   468→            if (this._innerRemoveCall > 0)
   469→                CCLOG("removeAllChildrenWithCleanup Error");
   470→
   471→            _children.Clear();
   472→        }
   473→
   474→        protected void detachChild(CCNode child, int childIndex, bool doCleanup)
   475→        {
   476→            if (child.isRunning() && !this._running)
   477→            {
   478→                CCLOG("No Call onExit");
   479→            }
   480→
   481→            if (_running)
   482→            {
   483→                child.onExitTransitionDidStart();
   484→                child.onExit();
   485→            }
   486→
   487→            if (doCleanup)
   488→                child.cleanup();
   489→
   490→            child.setParent(null);
   491→            if (this._innerRemoveCall > 0)
   492→                CCLOG("removeAllChildrenWithCleanup Error");
   493→
   494→            if (_children.Count > childIndex && _children[childIndex] == child)
   495→                _children.RemoveAt(childIndex);
   496→            else
   497→            {
   498→                var index = _children.IndexOf(child);
   499→                if (index < _children.Count && index >= 0)
   500→                    _children.RemoveAt(index);
   501→                else
   502→                    Debug.Assert(false, "Child must be in the children");
   503→            }
   504→        }
