   833→        protected void updateRotationQuat()
   834→        {
   835→            float halfRadx = CC_DEGREES_TO_RADIANS(_rotationX / 2f), halfRady = CC_DEGREES_TO_RADIANS(_rotationY / 2f), halfRadz = _rotationZ_X == _rotationZ_Y ? -CC_DEGREES_TO_RADIANS(_rotationZ_X / 2f) : 0;
   836→            float coshalfRadx = Mathf.Cos(halfRadx), sinhalfRadx = Mathf.Sin(halfRadx), coshalfRady = Mathf.Cos(halfRady), sinhalfRady = Mathf.Sin(halfRady), coshalfRadz = Mathf.Cos(halfRadz), sinhalfRadz = Mathf.Sin(halfRadz);
   837→            _rotationQuat.x = sinhalfRadx * coshalfRady * coshalfRadz - coshalfRadx * sinhalfRady * sinhalfRadz;
   838→            _rotationQuat.y = coshalfRadx * sinhalfRady * coshalfRadz + sinhalfRadx * coshalfRady * sinhalfRadz;
   839→            _rotationQuat.z = coshalfRadx * coshalfRady * sinhalfRadz - sinhalfRadx * sinhalfRady * coshalfRadz;
   840→            _rotationQuat.w = coshalfRadx * coshalfRady * coshalfRadz + sinhalfRadx * sinhalfRady * sinhalfRadz;
   841→
   842→            // 左右手坐标系是不同的，Unity为右手坐标系，Cocos为左手，四元数从左手转到右手x，y要取负数
   843→            this.transform.localRotation = new Quaternion(-_rotationQuat.x, -_rotationQuat.y, _rotationQuat.z, _rotationQuat.w);
   844→        }
   845→
   846→        protected void updateRotation3D()
   847→        {
   848→            float x = _rotationQuat.x, y = _rotationQuat.y, z = _rotationQuat.z, w = _rotationQuat.w;
   849→            _rotationX = Mathf.Atan2(2 * (w * x + y * z), 1 - 2 * (x * x + y * y));
   850→            _rotationY = Mathf.Asin(2 * (w * y - z * x));
   851→            _rotationZ_X = Mathf.Atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
   852→
   853→            _rotationX = CC_RADIANS_TO_DEGREES(_rotationX);
   854→            _rotationY = CC_RADIANS_TO_DEGREES(_rotationY);
   855→            _rotationZ_X = _rotationZ_Y = -CC_RADIANS_TO_DEGREES(_rotationZ_X);
   856→
   857→            // 左右手坐标系是不同的，Unity为右手坐标系，Cocos为左手，四元数从左手转到右手x，y要取负数
   858→            this.transform.localRotation = new Quaternion(-_rotationQuat.x, -_rotationQuat.y, _rotationQuat.z, _rotationQuat.w);
   859→        }
