  1708→        public virtual void Visit(ref int order)
  1709→        {
  1710→            if (!this.isVisible() || this.doNotVisit)
  1711→                return;
  1712→
  1713→            if (_children != null && _children.Count > 0)
  1714→            {
  1715→                sortAllChildren();
  1716→
  1717→                int i = 0;
  1718→                for (; i < _children.Count; i++)
  1719→                {
  1720→                    var node = _children[i];
  1721→                    if (node == null)
  1722→                        continue;
  1723→
  1724→                    if (node._localZOrder < 0)
  1725→                        node.Visit(ref order);
  1726→                    else
  1727→                        break;
  1728→                }
  1729→                SetTrueRenderOrder(order++);
  1730→                for (; i < _children.Count; i++)
  1731→                {
  1732→                    var node = _children[i];
  1733→                    if (node == null)
  1734→                        continue;
  1735→
  1736→                    node.Visit(ref order);
  1737→                }
  1738→            }
  1739→            else
  1740→            {
  1741→                SetTrueRenderOrder(order++);
  1742→            }
  1743→        }
