    39→        public void addAction(CCAction action, CCNode target, bool paused)
    40→        {
    41→            Debug.Assert(action != null, "");
    42→            Debug.Assert(target != null, "");
    43→
    44→            _hashElement element = null;
    45→            if (!this._targets.TryGetValue(target, out element))
    46→            {
    47→                element = new _hashElement();
    48→                element.paused = paused;
    49→                element.target = target;
    50→                this._targets.Add(target, element);
    51→                this._targetsList.Add(element);
    52→            }
    53→
    54→            actionAllocWithHashElement(element);
    55→
    56→            Debug.Assert(!element.actions.Contains(action), "");
    57→            element.actions.Add(action);
    58→            action.startWithTarget(target);
    59→        }
