    61→        public void removeAllActions()
    62→        {
    63→            List<CCNode> targets = new List<CCNode>();
    64→            foreach (var item in this._targets)
    65→                targets.Add(item.Key);
    66→
    67→            for (int i = 0; i < targets.Count; i++)
    68→                this.removeAllActionsFromTarget(targets[i]);
    69→        }
