    71→        public void removeAllActionsFromTarget(CCNode target)
    72→        {
    73→            if (target == null)
    74→                return;
    75→
    76→            _hashElement element = null;
    77→            if (this._targets.TryGetValue(target, out element))
    78→            {
    79→                if (element.actions.Contains(element.currentAction) && !element.currentActionSalvaged)
    80→                {
    81→                    element.currentActionSalvaged = true;
    82→                }
    83→
    84→                element.actions.Clear();
    85→                if (_currentTarget == element)
    86→                {
    87→                    _currentTargetSalvaged = true;
    88→                }
    89→                else
    90→                {
    91→                    deleteHashElement(element);
    92→                }
    93→            }
    94→            else
    95→            {
    96→
    97→            }
    98→        }
