   100→        public void removeAction(CCAction action)
   101→        {
   102→            if (action == null)
   103→                return;
   104→
   105→            _hashElement element = null;
   106→            if (this._targets.TryGetValue(action.getOriginalTarget(), out element))
   107→            {
   108→                var i = element.actions.IndexOf(action);
   109→                if (i >= 0)
   110→                    removeActionAtIndex(i, element);
   111→            }
   112→            else
   113→            {
   114→                Debug.Log("cocos2d: removeAction: Target not found");
   115→            }
   116→        }
