   118→        public void removeActionByTag(int tag, CCNode target)
   119→        {
   120→            Debug.Assert(tag != CCAction.INVALID_TAG, "");
   121→            Debug.Assert(target != null, "");
   122→
   123→            _hashElement element = null;
   124→            if (this._targets.TryGetValue(target, out element))
   125→            {
   126→                var limit = element.actions.Count;
   127→                for (int i = 0; i < limit; i++)
   128→                {
   129→                    CCAction action = element.actions[i];
   130→                    if (action.getTag() == tag && action.getOriginalTarget() == target)
   131→                    {
   132→                        removeActionAtIndex(i, element);
   133→                        break;
   134→                    }
   135→                }
   136→            }
   137→        }
   138→
   139→        public void removeAllActionsByTag(int tag, CCNode target)
   140→        {
   141→            Debug.Assert(tag != CCAction.INVALID_TAG, "");
   142→            Debug.Assert(target != null, "");
   143→
   144→            _hashElement element = null;
   145→            if (this._targets.TryGetValue(target, out element))
   146→            {
   147→                var limit = element.actions.Count;
   148→
   149→                for (int i = 0; i < limit;)
   150→                {
   151→                    CCAction action = element.actions[i];
   152→                    if (action.getTag() == tag && action.getOriginalTarget() == target)
   153→                    {
   154→                        removeActionAtIndex(i, element);
   155→                        --limit;
   156→                    }
   157→                    else
   158→                    {
   159→                        ++i;
   160→                    }
   161→                }
   162→            }
   163→        }
