   170→            {
   171→                if (element.actions != null)
   172→                {
   173→                    var limit = element.actions.Count;
   174→                    for (int i = 0; i < limit; ++i)
   175→                    {
   176→                        CCAction action = element.actions[i];
   177→
   178→                        if (action.getTag() == tag)
   179→                            return action;
   180→                    }
   181→                }
   182→            }
   183→            else
   184→            {
   185→
   186→            }
   187→            return null;
