   221→        public List<CCNode> pauseAllRunningActions()
   222→        {
   223→            List<CCNode> idsWithActions = new List<CCNode>();
   224→            foreach (var element in _targets.Values)
   225→            {
   226→                if (!element.paused)
   227→                {
   228→                    element.paused = true;
   229→                    idsWithActions.Add(element.target);
   230→                }
