   244→        public void update(float dt)
   245→        {
   246→            for (int i = _targetsList.Count - 1; i >= 0; i--)
   247→            {
   248→                if (i >= _targetsList.Count)
   249→                    continue;
   250→                _currentTarget = _targetsList[i];
   251→                _currentTargetSalvaged = false;
   252→
   253→                if (!_currentTarget.paused)
   254→                {
   255→                    for (_currentTarget.actionIndex = 0; _currentTarget.actionIndex < _currentTarget.actions.Count; _currentTarget.actionIndex++)
   256→                    {
   257→                        _currentTarget.currentAction = _currentTarget.actions[_currentTarget.actionIndex];
   258→                        if (_currentTarget.currentAction == null)
   259→                            continue;
   260→
   261→                        _currentTarget.currentActionSalvaged = false;
   262→
   263→                        _currentTarget.currentAction.step(dt);
   264→
   265→                        if (_currentTarget.currentActionSalvaged)
   266→                        {
   267→                            //_currentTarget.currentAction = null;
   268→                        }
   269→                        else if (_currentTarget.currentAction.isDone())
   270→                        {
   271→                            _currentTarget.currentAction.stop();
   272→
   273→                            CCAction action = _currentTarget.currentAction;
   274→
   275→                            _currentTarget.currentAction = null;
   276→                            removeAction(action);
   277→                        }
   278→
   279→                        _currentTarget.currentAction = null;
   280→                    }
   281→                }
   282→
   283→                if (_currentTargetSalvaged && _currentTarget.actions.Count == 0)
   284→                {
   285→                    deleteHashElement(_currentTarget);
   286→                }
   287→            }
   288→
   289→            _currentTarget = null;
   290→        }
   291→
   292→        protected void removeActionAtIndex(int index, _hashElement element)
   293→        {
   294→            CCAction action = element.actions[index];
   295→
   296→            if (action == element.currentAction && !element.currentActionSalvaged)
   297→            {
   298→                element.currentActionSalvaged = true;
   299→            }
   300→
   301→            element.actions.RemoveAt(index);
   302→
   303→            if (element.actionIndex >= index)
   304→                element.actionIndex--;
   305→
   306→            if (element.actions.Count == 0)
   307→            {
   308→                if (_currentTarget == element)
   309→                    _currentTargetSalvaged = true;
   310→                else
   311→                    deleteHashElement(element);
   312→            }
   313→        }
   314→
   315→        protected void deleteHashElement(_hashElement element)
   316→        {
   317→            element.actions.Clear();
   318→            this._targets.Remove(element.target);
   319→            this._targetsList.Remove(element);
   320→            element.target = null;
   321→            element = null;
   322→        }
   323→
   324→        protected void actionAllocWithHashElement(_hashElement element)
   325→        {
   326→            if (element.actions == null)
   327→                element.actions = new List<CCAction>();
   328→        }
   329→    }
   330→}

