     8→    public class CCActionInterval : CCFiniteTimeAction
     9→    {
    10→        protected float _elapsed;
    11→        protected bool _firstTick;
    12→        protected bool _done;
    13→
    14→        public float getElapsed() { return _elapsed; }
    15→
    16→        public virtual void setAmplitudeRate(float amp) { }
    17→
    18→        public virtual float getAmplitudeRate() { return 0; }
