    25→        public override void step(float dt)
    26→        {
    27→            if (_firstTick)
    28→            {
    29→                _firstTick = false;
    30→                _elapsed = 0;
    31→            }
    32→            else
    33→            {
    34→                _elapsed += dt;
    35→            }
    36→
    37→            //float updateDt = Mathf.Clamp01(_elapsed / _duration);
    38→            //在此处出现NaN，修改一下
    39→            float _value = 0;
    40→            if (_duration == 0)
    41→            {
    42→                _value = 1;
    43→            }
    44→            else
    45→            {
    46→                _value = _elapsed / _duration;
    47→            }
    48→            float updateDt = Mathf.Clamp01(_value);
    49→
    50→            if (sendUpdateEventToScript(updateDt, this)) return;
    51→
    52→            this.update(updateDt);
    53→
    54→            _done = _elapsed >= _duration;
    55→        }
    56→
